// fix-health-app-v2.4.10.cjs — Family Health Track v2.4.10 one-step fix
// Run from the project root (the folder with package.json) with:
//   node fix-health-app-v2.4.10.cjs
// Requires v2.4.9 already applied (run fix-health-app-v2.4.9.cjs first if you
// are still on v2.4.8). What it does:
//   1. Backs up each changed file to <file>.bak (first run only)
//   2. Applies the v2.4.10 fix — ALL 10 of the most important audit issues:
//      family-member records filed under the right person (with a
//      "ကိုယ်တိုင်"/"အားလုံး" switch), admin add-user no longer leaves a
//      phantom user, Google login timeout + real login error messages,
//      medication dose times + real "taken" logging + honest adherence %,
//      complete backup/restore (no invented values), Emergency ID that
//      stays saved + prints fully, Health Passport with real data, all
//      fabricated demo data removed, Q&A answers now notify the user
//   3. Runs npm install, typecheck (tsc), tests (vitest) and build
// Safe to run twice: files already matching the new content are skipped.
// It does NOT touch your data, your Firebase project, or git.
// IMPORTANT: this version changes firestore.rules (family-member filing,
// admin add-user, cross-user Q&A notifications). The file is updated by
// this script, but rules only take effect after YOU publish them:
// Firebase Console > Firestore Database > Rules > Publish. Until then,
// family-member filing still works through the email fallback, but the
// new rules are not active.
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const VERSION = '2.4.10';
const FILES = [
  {
    "path": "package.json",
    "b64": ""
  },
  {
    "path": "firestore.rules",
    "b64": ""
  },
  {
    "path": "src/constants/version.ts",
    "b64": "ZXhwb3J0IGNvbnN0IENVUlJFTlRfU1lTVEVNX1ZFUlNJT04gPSAndjIuNC4xMCc7Cg=="
  },
  {
    "path": "src/types/health.ts",
    "b64": ""
  },
  {
    "path": "src/context/AuthContext.tsx",
    "b64": ""
  },
  {
    "path": "src/context/HealthDataContext.tsx",
    "b64": ""
  },
  {
    "path": "src/context/NotificationContext.tsx",
    "b64": ""
  },
  {
    "path": "src/components/auth/LoginScreen.tsx",
    "b64": ""
  },
  {
    "path": "src/components/family/FamilyMembersBar.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/BMIModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/MedicationsModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/DataBackupModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/EmergencyIDModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/HealthPassportModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/PregnancyCareModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/PhysiotherapyModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/NotificationCenterModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/VersionHistoryModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/AdminPatientPortal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminAddPatientModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminPatientDetail.tsx",
    "b64": ""
  }
];

const norm = (s) => String(s).replace(/\r\n/g, '\n');
let applied = 0, skipped = 0, failed = 0;
const failures = [];

function run(cmd, args, label) {
  console.log('  $ ' + cmd + ' ' + args.join(' '));
  const r = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error || r.status !== 0) {
    console.log('[FAIL] ' + label + ' (exit ' + (r.status ?? r.error) + ')');
    return false;
  }
  console.log('[OK] ' + label);
  return true;
}

function main() {
  console.log('Family Health Track fix — v' + VERSION);
  console.log('Project folder: ' + process.cwd());
  const pkgPath = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    console.log('[ERROR] package.json not found here. Run this script from the project root (the folder with package.json).');
    process.exit(1);
  }
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch (e) {
    console.log('[ERROR] package.json could not be read: ' + e.message);
    process.exit(1);
  }
  if (pkg.name !== 'family-health-track') {
    console.log('[ERROR] This does not look like the Family Health Track project (package name: ' + pkg.name + '). Stopping.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.8') {
    console.log('[ERROR] This project is still v2.4.8. Run fix-health-app-v2.4.9.cjs first, then run this script again.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.7') {
    console.log('[ERROR] This project is still v2.4.7. Run fix-health-app-v2.4.8.cjs, then fix-health-app-v2.4.9.cjs, then run this script again.');
    process.exit(1);
  }
  if (!['2.4.9', '2.4.10'].includes(String(pkg.version))) {
    console.log('[ERROR] Unexpected project version ' + pkg.version + ' (expected 2.4.9). Stopping — ask for help before running this.');
    process.exit(1);
  }

  for (const f of FILES) {
    const dest = path.join(process.cwd(), ...f.path.split('/'));
    const next = Buffer.from(f.b64, 'base64').toString('utf8');
    try {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      if (fs.existsSync(dest) && norm(fs.readFileSync(dest, 'utf8')) === norm(next)) {
        console.log('[SKIP] already applied: ' + f.path);
        skipped++;
        continue;
      }
      if (fs.existsSync(dest) && !fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.writeFileSync(dest, next, 'utf8');
      console.log('[OK] applied: ' + f.path);
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + f.path + ': ' + e.message);
      failed++;
      failures.push(f.path + ': ' + e.message);
    }
  }
  console.log('');
  console.log('Applied ' + applied + ' | Already applied ' + skipped + ' | Failed ' + failed);
  if (failed > 0) {
    console.log('Failures: ' + failures.join(' ; '));
    console.log('Stopping before checks. Your .bak backups are next to the originals.');
    process.exit(1);
  }

  console.log('');
  console.log('--- checks (npm install, typecheck, tests, build) ---');
  const okInstall = run('npm', ['install', '--no-audit', '--no-fund'], 'npm install');
  const okLint = run('npx', ['tsc', '--noEmit'], 'typecheck (tsc --noEmit)');
  const okTest = run('npx', ['vitest', 'run'], 'tests (vitest run)');
  const okBuild = run('npm', ['run', 'build'], 'build (vite build)');
  if (!okInstall || !okLint || !okTest || !okBuild) {
    console.log('');
    console.log('[DONE WITH ERRORS] Files were updated, but a check failed above.');
    console.log('Do NOT deploy yet. Ask for help and include the error lines above.');
    process.exit(1);
  }

  console.log('');
  console.log('[DONE] v' + VERSION + ' applied. Applied ' + applied + ' | Already applied ' + skipped + ' | Failed 0');
  console.log('');
  console.log('NEXT STEPS (do these in order):');
  console.log('  1. Publish the new Firestore rules (this version needs them):');
  console.log('     Firebase Console > Firestore Database > Rules > Publish.');
  console.log('     Without this, family-member filing and Q&A notifications');
  console.log('     will not work fully. Admin add-user also needs the rules.');
  console.log('  2. Deploy / push the app (git push, then Cloudflare redeploys).');
  console.log('  3. On your device, hard-refresh once (Ctrl+Shift+R).');
  console.log('     Version History must show v2.4.10.');
  console.log('  4. Try: pick a family member, add a BP record — it must be');
  console.log('     filed under them, and "ကိုယ်တိုင်" must show only your own.');
  console.log('     Add a dose time to a medicine; mark it taken from the');
  console.log('     notification and check it is really logged.');
}

main();
